package com.xyz.question_bank_management_system.modules.agent.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;import com.xyz.question_bank_management_system.config.CorrelationContext;import com.xyz.question_bank_management_system.exception.*;import com.xyz.question_bank_management_system.modules.agent.entity.*;import com.xyz.question_bank_management_system.modules.agent.mapper.PersonalizedResourceMapper;import com.xyz.question_bank_management_system.modules.agent.service.ResourceBlueprintService;import com.xyz.question_bank_management_system.modules.agent.tool.*;import com.xyz.question_bank_management_system.modules.learning.entity.LearningPathItem;import com.xyz.question_bank_management_system.modules.learning.mapper.LearningPathV1Mapper;import com.xyz.question_bank_management_system.modules.profile.entity.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.util.*;
@Service @RequiredArgsConstructor public class ResourceBlueprintServiceImpl implements ResourceBlueprintService {private final PersonalizedResourceMapper mapper;private final LearningPathV1Mapper pathMapper;private final KnowledgeStateQueryTool knowledgeTool;private final ResourcePreferenceQueryTool preferenceTool;private final KnowledgeGraphSearchTool graphTool;private final CourseResourceCapabilityQueryTool capabilityTool;private final ObjectMapper objectMapper;
 @Override @Transactional public ResourceBlueprint design(Long studentId,ResourceUnit unit){List<Long> ids=pathMapper.selectSteps(unit.getPathVersionId()).stream().filter(x->mapper.selectConsumedSteps(unit.getPathVersionId()).stream().anyMatch(c->Objects.equals(c.getPathStepId(),x.getId())&&Objects.equals(c.getResourceUnitId(),unit.getId()))).sorted(Comparator.comparing(LearningPathItem::getOrderNo)).map(LearningPathItem::getKnowledgePointId).toList();if(ids.isEmpty())throw BizException.of(ErrorCode.FAILED_INPUT,"ResourceUnit 没有路径步骤");Map<String,Object> states=knowledgeTool.query(studentId,unit.getCourseId(),ids);Map<String,Object> preferences=preferenceTool.query(studentId,unit.getCourseId());Map<String,Object> graph=graphTool.query(unit.getCourseId(),ids);List<String> capabilities=capabilityTool.query(unit.getCourseId());Map<Long,BigDecimal> mastery=new HashMap<>();Object rawStates=states.get("states");if(rawStates instanceof Collection<?> rows)for(Object row:rows)if(row instanceof StudentKnowledgeState s)mastery.put(s.getKnowledgePointId(),s.getMasteryValue());List<Map<String,Object>> resourcePlan=new ArrayList<>();int slot=0;for(Long id:ids){BigDecimal m=mastery.getOrDefault(id,new BigDecimal("0.30"));String type=capabilities.contains("concept_explanation")?"concept_explanation":capabilities.get(0);Map<String,Object> r=new LinkedHashMap<>();r.put("resourceSlotId","rs_"+(++slot));r.put("resourceType",type);r.put("knowledgePointIds",List.of(id));r.put("instructionalPurpose","建立或强化当前知识表征");r.put("scaffoldingLevel",m.compareTo(new BigDecimal("0.50"))<0?"HIGH":"MEDIUM");r.put("selectionReason","mastery="+m+"，结合教学作用、资源偏好与课程能力选择");r.put("profileEvidence",List.of("knowledgePoint="+id+",mastery="+m));resourcePlan.add(r);}List<Map<String,Object>> learning=new ArrayList<>(),hidden=new ArrayList<>();int q=0;for(Long id:ids){BigDecimal m=mastery.getOrDefault(id,new BigDecimal("0.30"));BigDecimal difficulty=BigDecimal.ONE.subtract(m).max(new BigDecimal("0.20")).min(new BigDecimal("0.90")).setScale(4,RoundingMode.HALF_UP);learning.add(question("lq_"+(++q),"VISIBLE","LEARNING_PRACTICE",id,ids,"single_choice","UNDERSTAND",difficulty,false));hidden.add(question("ha_"+q,"HIDDEN_UNTIL_ASSESSMENT","KNOWLEDGE_ASSESSMENT",id,ids,"short_answer","APPLY",difficulty,true));}try{ResourceBlueprint b=new ResourceBlueprint();b.setBlueprintCode("bp_"+UUID.randomUUID().toString().replace("-",""));b.setResourceUnitId(unit.getId());b.setProfileVersionUsed(((Number)states.getOrDefault("profileVersion",0)).longValue());b.setPolicyVersion("resource_policy_v1");b.setStatus("READY");b.setResourcePlanJson(objectMapper.writeValueAsString(resourcePlan));b.setLearningQuestionPlanJson(objectMapper.writeValueAsString(learning));b.setHiddenAssessmentPlanJson(objectMapper.writeValueAsString(hidden));b.setProfileEvidenceJson(objectMapper.writeValueAsString(Map.of("knowledge",states,"preferences",preferences)));b.setGraphEvidenceJson(objectMapper.writeValueAsString(graph));b.setCapabilitySnapshotJson(objectMapper.writeValueAsString(capabilities));b.setSchemaVersion("personalized-resource-blueprint-v1");b.setCorrelationId(CorrelationContext.get());mapper.insertBlueprint(b);return b;}catch(Exception ex){throw new IllegalStateException("蓝图序列化失败",ex);}}
 private Map<String,Object> question(String slot,String visibility,String purpose,Long primary,List<Long> ids,String type,String cognitive,BigDecimal difficulty,boolean hidden){Map<String,Object> q=new LinkedHashMap<>();q.put("questionSlotId",slot);q.put("visibility",visibility);q.put("purpose",purpose);q.put("primaryKnowledgePointId",primary);q.put("knowledgePointIds",ids);q.put("questionType",type);q.put("questionDifficulty",difficulty);q.put("cognitiveLevel",cognitive);q.put("cognitiveDefinition","UNDERSTAND".equals(cognitive)?"从教学信息中建构意义。":"在给定或新情境中使用已有知识。");q.put("requiredCognitiveActions",List.of("UNDERSTAND".equals(cognitive)?"解释与比较":"识别情境并应用知识"));q.put("cognitiveLevelReason","依据当前掌握状态和测量目标确定");q.put("assessmentObjective","获取知识点 "+primary+" 的"+(hidden?"独立应用":"理解")+"证据");if(hidden)q.put("noveltyRequirement","不得复用普通题库、可见练习、例题或历史检测题");return q;}
}
